  'हों': { en: 'हों', ipa: '/hoːn/', pos: 'n' },
  'होंगे': { en: 'होंगे', ipa: '/hoːnɡeː/', pos: 'v' },
  'होंठ': { en: 'lip', ipa: '/hoːnʈʰ/', pos: 'n' },
  'होकर': { en: 'होकर', ipa: '/hoːkər/', pos: 'n' },
  'होगा': { en: 'will be (m)', ipa: '/hoːɡaː/', pos: 'v' },
  'होगी': { en: 'will be (f)', ipa: '/hoːɡiː/', pos: 'v' },
  'होता': { en: 'happens/is (hab.m)', ipa: '/hoːtaː/', pos: 'v' },
  'होती': { en: 'happens/is (hab.f)', ipa: '/hoːtiː/', pos: 'v' },
  'होते': { en: 'happen/are (hab.pl)', ipa: '/hoːteː/', pos: 'v' },
  'होनी': { en: 'होनी', ipa: '/hoːniː/', pos: 'n' },
  'होने': { en: 'होने', ipa: '/hoːneː/', pos: 'n' },
  'होमवर्क': { en: 'homework', ipa: '/hoːməʋərk/', pos: 'n' },
  'होय': { en: 'होय', ipa: '/hoːj/', pos: 'n' },
  'होली': { en: 'Holi', ipa: '/hoːliː/', pos: 'n' },
  'होश': { en: 'होश', ipa: '/hoːʃ/', pos: 'n' },
  'होशियार': { en: 'होशियार', ipa: '/hoːʃɪjaːr/', pos: 'n' },
